def retry(times=3, on=(ValueError,)):
    def deco(fn):
        def inner(*args, **kwargs):
            for attempt in range(1, times + 1):
                try:
                    return fn(*args, **kwargs)
                except on:
                    if attempt == times:
                        raise
        return inner
    return deco

@retry(times=2, on=(ValueError, KeyError))
def flaky(d):
    return d["k"]

from functools import wraps

def once(fn):
    @wraps(fn)
    def inner(*args, **kwargs):
        if not inner.done:
            inner.value = fn(*args, **kwargs)
            inner.done = True
        return inner.value
    inner.done = False
    return inner

@once
def setup():
    """Build the thing exactly once."""
    return {"ready": True}

